const ast = @import("../../ast.zig");
const petscii = @import("../../petscii.zig");

pub fn emitBasicStub(writer: anytype, load_addr: u16, entry_addr: u16) !void {
    try writer.print(
        "; generated by zp64c\n* = ${x:0>4}\n    .word basic_next\n    .word 10\n    .byte $9e\n    .text \"{d}\"\n    .byte 0\nbasic_next:\n    .word 0\n\n",
        .{ load_addr, entry_addr },
    );
}

pub fn nextPrintArg(print: ast.ConsolePrint, arg_index: *usize) !ast.PrintArg {
    if (arg_index.* >= print.args.len) return error.MissingFormatArgument;
    const arg = print.args[arg_index.*];
    arg_index.* += 1;
    return arg;
}

pub fn screenAddress(x: u8, y: u8) u16 {
    return 0x0400 + (@as(u16, y) * 40) + x;
}

pub fn colorAddress(x: u8, y: u8) u16 {
    return 0xd800 + (@as(u16, y) * 40) + x;
}

pub fn colorAddressFromScreen(screen_address: u16) u16 {
    return 0xd800 + (screen_address - 0x0400);
}

pub fn screenCode(ch: u8) u8 {
    return petscii.petsciiToScreenCode(ch);
}

pub fn emitClearScreenRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\clearScreen:
        \\    ldx #0
        \\    lda #32
        \\    ; Keep the 15-byte loop and taken-branch PC in one page.
        \\.if (* & $ff) > $f0
        \\    jmp clearScreenLoop
        \\.if (* & $ff) > $f0
        \\    .fill (($100 - (* & $ff)) & $ff),0
        \\.endif
        \\.endif
        \\clearScreenLoop:
        \\    sta $0400,x
        \\    sta $0500,x
        \\    sta $0600,x
        \\    sta $06e8,x
        \\    inx
        \\    bne clearScreenLoop
        \\    rts
        \\
    );
}

