        \\    lda $0428,x
        \\    sta $0400,x
        \\    lda $0528,x
        \\    sta $0500,x
        \\    lda $0628,x
        \\    sta $0600,x
        \\    lda $d828,x
        \\    sta $d800,x
        \\    lda $d928,x
        \\    sta $d900,x
        \\    lda $da28,x
        \\    sta $da00,x
