        \\    sta $07c0,x
        \\    inx
        \\    cpx #40
        \\    bne consoleClearLastLine
        \\    ldx #0
        \\    lda #1
        \\consoleColorLastLine:
        \\    sta $dbc0,x
        \\    inx
        \\    cpx #40
        \\    bne consoleColorLastLine
        \\    rts
