pub fn emitConsoleHexRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\consolePutHexByte:
        \\    sta zeropage_hex_tmp
        \\    lsr
        \\    lsr
        \\    lsr
        \\    lsr
        \\    jsr hexNibbleToScreen
        \\    jsr consolePutChar
        \\    lda zeropage_hex_tmp
        \\    jsr hexNibbleToScreen
        \\    jsr consolePutChar
        \\    rts
        \\
    );
}

pub fn emitKernalStringRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\kernalPutString:
        \\    sta zeropage_kernal_string_len
        \\    lda #0
        \\    sta zeropage_kernal_string_index
        \\kernalPutStringLoop:
        \\    lda zeropage_kernal_string_index
        \\    cmp zeropage_kernal_string_len
        \\    beq kernalPutStringDone
        \\    tay
        \\    lda (zeropage_kernal_ptr),y
        \\    jsr $ffd2
        \\    inc zeropage_kernal_string_index
        \\    jmp kernalPutStringLoop
        \\kernalPutStringDone:
        \\    rts
        \\
    );
}

pub fn emitKeyboardWaitRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\keyboardWaitPetscii:
        \\keyboardWaitPetsciiDown:
        \\    jsr $ffe4
        \\    cmp #0
        \\    beq keyboardWaitPetsciiDown
        \\    sta zeropage_keyboard_key
        \\keyboardWaitPetsciiUp:
        \\    jsr $ffe4
        \\    cmp #0
        \\    bne keyboardWaitPetsciiUp
        \\    lda zeropage_keyboard_key
        \\    rts
        \\
    );
}

pub fn emitStringRuntimeRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\stringAppend:
        \\    lda #0
        \\    sta zeropage_string_index
        \\stringAppendLoop:
        \\    lda zeropage_string_index
        \\    cmp zeropage_string_src_len
        \\    beq stringAppendDone
        \\    lda zeropage_string_dst_len
        \\    cmp zeropage_string_dst_cap
        \\    beq stringAppendDone
        \\    ldy zeropage_string_index
        \\    lda (zeropage_string_src_ptr),y
        \\    ldy zeropage_string_dst_len
        \\    sta (zeropage_string_dst_ptr),y
        \\    inc zeropage_string_index
        \\    inc zeropage_string_dst_len
        \\    jmp stringAppendLoop
        \\stringAppendDone:
        \\    rts
        \\
    );
}

pub fn emitHexNibbleRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\hexNibbleToScreen:
        \\    and #$0f
        \\    cmp #10
        \\    bcc hexNibbleDigit
        \\    sec
        \\    sbc #9
        \\    rts
        \\hexNibbleDigit:
        \\    clc
        \\    adc #48
        \\    rts
        \\
    );
}

pub const multiply_word_routine =
    \\zeropage_mul16:
    \\    lda #0
    \\    sta zeropage_mul_result
    \\    sta zeropage_mul_result+1
    \\    ldx #16
    \\    ; The 36-byte loop's branch PC must not cross the page either.
    \\.if (* & $ff) > $db
    \\    jmp zeropage_mul16_loop
    \\.if (* & $ff) > $db
    \\    .fill (($100 - (* & $ff)) & $ff),0
    \\.endif
    \\.endif
    \\zeropage_mul16_loop:
    \\    ; ROR exposes the original low bit directly in carry.
    \\    lsr zeropage_mul_rhs+1
    \\    ror zeropage_mul_rhs
    \\    bcc zeropage_mul16_skip_add
    \\    lda zeropage_mul_result
    \\    clc
    \\    adc zeropage_mul_lhs
    \\    sta zeropage_mul_result
    \\    lda zeropage_mul_result+1
    \\    adc zeropage_mul_lhs+1
    \\    sta zeropage_mul_result+1
    \\zeropage_mul16_skip_add:
    \\    asl zeropage_mul_lhs
    \\    rol zeropage_mul_lhs+1
    \\    dex
    \\    bne zeropage_mul16_loop
    \\    lda zeropage_mul_result
    \\    ldx zeropage_mul_result+1
    \\    rts
    \\
;

pub fn emitMultiplyRoutine(writer: anytype) !void {
    try writer.writeAll(multiply_word_routine);
}

pub fn emitShiftRoutines(writer: anytype) !void {
    try writer.writeAll(
        \\zeropage_shl16:
        \\    sta zeropage_shift_value
        \\    stx zeropage_shift_value+1
        \\    lda zeropage_shift_count
        \\    beq zeropage_shl16_done
        \\zeropage_shl16_loop:
        \\    asl zeropage_shift_value
        \\    rol zeropage_shift_value+1
        \\    dec zeropage_shift_count
        \\    bne zeropage_shl16_loop
        \\zeropage_shl16_done:
        \\    lda zeropage_shift_value
        \\    ldx zeropage_shift_value+1
        \\    rts
        \\
        \\zeropage_shr16:
        \\    sta zeropage_shift_value
        \\    stx zeropage_shift_value+1
        \\    lda zeropage_shift_count
        \\    beq zeropage_shr16_done
        \\zeropage_shr16_loop:
        \\    lsr zeropage_shift_value+1
        \\    ror zeropage_shift_value
        \\    dec zeropage_shift_count
        \\    bne zeropage_shr16_loop
        \\zeropage_shr16_done:
        \\    lda zeropage_shift_value
        \\    ldx zeropage_shift_value+1
        \\    rts
        \\
    );
}

pub fn emitSleepRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\sleepTicks:
        \\    sta zeropage_sleep_count
        \\    beq sleepTicksDone
        \\sleepTicksOuter:
        \\    lda $dc04
        \\sleepTicksWait:
        \\    cmp $dc04
        \\    beq sleepTicksWait
        \\    dec zeropage_sleep_count
        \\    bne sleepTicksOuter
        \\sleepTicksDone:
        \\    rts
        \\
    );
}

pub fn emitSleepFramesRoutine(writer: anytype) !void {
    try writer.writeAll(
        \\sleepFrames:
        \\    sta zeropage_sleep_count
        \\    beq sleepFramesDone
        \\sleepFramesOuter:
        \\    lda #0
        \\sleepFramesWaitNotZero:
        \\    cmp $d012
        \\    beq sleepFramesWaitNotZero
        \\sleepFramesWaitZero:
        \\    lda $d012
        \\    bne sleepFramesWaitZero
        \\    dec zeropage_sleep_count
        \\    bne sleepFramesOuter
        \\sleepFramesDone:
        \\    rts
        \\
    );
}
